{
  "branches": [
    "master",
    {
      "name": "develop",
      "prerelease": "dev"
    }
  ],
  "plugins": [
    [
      "@semantic-release/commit-analyzer",
      {
        "preset": "conventionalcommits"
      }
    ],
    [
      "@semantic-release/release-notes-generator",
      {
        "preset": "conventionalcommits"
      }
    ],
    [
      "@semantic-release/changelog",
      {
        "changelogFile": "docs/reference/changelog.md"
      }
    ],
    [
      "@semantic-release/exec",
      {
        "prepareCmd": "sed -i 's/^version = .*/version = \"${nextRelease.version}\"/' pyproject.toml"
      }
    ],
    [
      "@semantic-release/git",
      {
        "assets": [
          "pyproject.toml",
          "docs/reference/changelog.md"
        ],
        "message": "chore(release): ${nextRelease.version} [skip ci]\n\n${nextRelease.notes}"
      }
    ],
    "@semantic-release/github"
  ]
}

{
  "$schema": "https://docs.renovatebot.com/renovate-schema.json",
  "extends": [
    "config:recommended",
    ":preserveSemverRanges",
    "group:allNonMajor"
  ],
  "timezone": "Europe/Lisbon",
  "schedule": ["before 6am on monday"],
  "labels": ["dependencies"],
  "prConcurrentLimit": 5,
  "packageRules": [
    {
      "matchManagers": ["pip_requirements", "pep621"],
      "matchUpdateTypes": ["major"],
      "dependencyDashboardApproval": true
    },
    {
      "matchManagers": ["github-actions"],
      "groupName": "GitHub Actions",
      "automerge": true,
      "automergeType": "pr",
      "platformAutomerge": true
    }
  ],
  "python": {
    "enabled": true
  }
}

{
  "name": "ydata-profiling",
  "build": {
    "dockerfile": "Dockerfile",
    "context": ".."
  },
  "customizations": {
    "vscode": {
      "settings": {
        "python.defaultInterpreterPath": "/usr/local/bin/python",
        "python.testing.pytestEnabled": true,
        "python.testing.pytestArgs": ["tests"],
        "editor.formatOnSave": true,
        "editor.codeActionsOnSave": {
          "source.organizeImports": "explicit"
        },
        "[python]": {
          "editor.defaultFormatter": "ms-python.black-formatter"
        }
      },
      "extensions": [
        "ms-python.python",
        "ms-python.black-formatter",
        "charliermarsh.ruff",
        "redhat.vscode-yaml",
        "yzhang.markdown-all-in-one"
      ]
    }
  },
  "postCreateCommand": "pip install -e '.[test,unicode]' && pre-commit install || true",
  "remoteUser": "vscode"
}

/* Custom styles for the ydata-profiling documentation. */

:root {
  --yp-accent: #522d80;
}

/* Brand-colored header accents */
.md-header {
  background-color: var(--yp-accent);
}

/* Slightly wider content column for code-heavy pages */
.md-grid {
  max-width: 78rem;
}

/* Inline code legibility */
.md-typeset code {
  font-size: 0.85em;
}

/* Keep long tables from overflowing the content area */
.md-typeset__table {
  display: block;
  overflow-x: auto;
}

/* Admonition titles matching the brand accent */
.md-typeset .admonition.note > .admonition-title,
.md-typeset details.note > summary {
  border-left-color: var(--yp-accent);
}

"""Vektis (Dutch healthcare costs) example.

Original data source: Vektis open data on Dutch healthcare expenditures
https://www.vektis.nl/streams/open-data
Synthetic equivalents of the two source files (care types and yearly costs)
are generated and merged, mirroring the multi-file workflow of the real
example.
"""

import numpy as np
import pandas as pd

from ydata_profiling import ProfileReport


def load_care_types(seed: int = 37) -> pd.DataFrame:
    rng = np.random.default_rng(seed)
    return pd.DataFrame(
        {
            "care_type_id": np.arange(1, 13),
            "care_type": [
                "huisartsenzorg", "ziekenhuiszorg", "farmaceutische zorg",
                "geestelijke gezondheidszorg", "paramedische zorg",
                "verpleging en verzorging", "geboortezorg", "tandzorg",
                "hulpmiddelen", "vervoer", "grensoverschrijdende zorg",
                "overige zorg",
            ],
            "specialism": rng.choice(
                ["general", "mental", "dental", "pharma", "other"], size=12
            ),
        }
    )


def load_yearly_costs(n: int = 2000, seed: int = 41) -> pd.DataFrame:
    rng = np.random.default_rng(seed)
    return pd.DataFrame(
        {
            "care_type_id": rng.integers(1, 13, size=n),
            "year": rng.choice([2021, 2022, 2023], size=n),
            "age_band": rng.choice(
                ["0-17", "18-44", "45-64", "65-79", "80+"], size=n
            ),
            "sex": rng.choice(["man", "vrouw"], size=n),
            "region": rng.choice(
                ["Noord", "Oost", "Zuid", "West"], size=n, p=[0.15, 0.2, 0.25, 0.4]
            ),
            "costs_eur": rng.lognormal(7.0, 1.2, size=n).round(2),
            "n_patients": rng.poisson(150, size=n) + 1,
        }
    )


if __name__ == "__main__":
    care_types = load_care_types()
    costs = load_yearly_costs()
    df = costs.merge(care_types, on="care_type_id", how="left")

    profile = ProfileReport(
        df,
        title="Vektis Healthcare Costs (synthetic, merged extract)",
    )
    profile.to_file("vektis_report.html")

